def names_to_programs(apps, schema_editor):
    """Each distinct typed program name becomes a Program (matched ignoring case and spacing), linked to the
    operator of its aircraft when they all agree."""
    Aircraft, Program = apps.get_model("tracker", "Aircraft"), apps.get_model("tracker", "Program")
    by_key = {}
    for a in Aircraft.objects.exclude(program_name=""):
        name = " ".join(a.program_name.split())
        if name:
            by_key.setdefault(name.lower(), (name, []))[1].append(a)
    for name, aircraft in by_key.values():
        operators = {a.operator_id for a in aircraft}
        program = Program.objects.create(name=name, operator_id=operators.pop() if len(operators) == 1 else None)
        Aircraft.objects.filter(pk__in=[a.pk for a in aircraft]).update(program=program)


def programs_to_names(apps, schema_editor):
    Aircraft = apps.get_model("tracker", "Aircraft")
    for a in Aircraft.objects.exclude(program=None).select_related("program"):
        a.program_name = a.program.name
        a.save(update_fields=["program_name"])


